import {test,after} from 'node:test';
import assert from 'node:assert/strict';
import {build} from 'esbuild';
import {JSDOM} from 'jsdom';
import {readFileSync} from 'node:fs';
import {fileURLToPath} from 'node:url';
import {createRequire} from 'node:module';
import {createHash} from 'node:crypto';
const require=createRequire(import.meta.url);
const src=fileURLToPath(new URL('../src/',import.meta.url));
const code=(await build({entryPoints:[src+'pipsClient.js'],bundle:true,write:false,loader:{'.css':'empty'},format:'iife'})).outputFiles[0].text;
const view=(await build({entryPoints:[src+'pipsView.ts'],bundle:true,write:false,platform:'node',format:'cjs',external:['vscode']})).outputFiles[0].text;
const module={exports:{}};new Function('module','exports','require',view)(module,module.exports,name=>name==='vscode'?{}:require(name));
const pure=(await build({entryPoints:[src+'pipsModel.js'],bundle:true,write:false,platform:'node',format:'cjs'})).outputFiles[0].text;
const model={exports:{}};new Function('module','exports',pure)(model,model.exports);
const windows=[];after(()=>windows.forEach(w=>w.close()));
const ws={id:'ws',name:'Project'};
const job=(id='a',extra={})=>({id,workspace_id:'ws',name:'Auditor '+id,goal:'Find source issues',source_ref:'HEAD',status:'active',current_version:1,policy:'read_only',trigger:'manual',proposals:[],...extra});
const finding={title:'Check boundary',severity:'medium',path:'src/main.py',line:4,evidence:'value = source()',verification:'source_excerpt_only'};
const report={summary:'Review this edge case.',findings:[finding],limitations:['No runtime verification.'],verification:'source_excerpt_only',tests_executed:false};
const run=(id='r1',pip='a',extra={})=>({id,pip_id:pip,status:'succeeded',created_at:'2026-10-01T10:00:00Z',manifest:{job_version:1,source_revision:'a'.repeat(40),workspace_context:{workspace_id:'ws',revision:2,entries:[],digest:'a'.repeat(64)}},result:report,...extra});
const runner={runner_id:'runner',status:'running',online:true,paused:false,counts:{queued:0,running:0,cancelling:0}};
const ctx={workspace_id:'ws',revision:2,entries:[]};
const types=['core','scout','lens','patch','rook','pulse','lock','quill'].map((id,character_index)=>{const available=['scout','lens','rook','lock'].includes(id),name=id[0].toUpperCase()+id.slice(1);return{id,name,character_index,role:{core:'Main chat',scout:'Repository exploration',lens:'Repository research',patch:'Code changes',rook:'Code review',pulse:'Test execution',lock:'Security review',quill:'Documentation writing'}[id],description:available?'Inspect committed source with a focused read-only preset.':'This role is planned.',available,unavailable_reason:available?null:'This engine is not available yet.',default_name:name+' job',default_goal:available?'Inspect source for '+id+' findings.':'',engine:available?'source_audit':null};});

async function flush(){for(let i=0;i<12;i++)await Promise.resolve();}
function setup({workspaceValue=ws,apiVersion=9,jobs=[job()],runs=[run()],enabled=true,runnerValue=runner,contextValue=ctx,typesValue=types,observe=false,conversation=false,autoSelect=true,messages=[],chatActive=null,manualMount=false,modelsValue={default_model:'default-model',models:[{id:'model-a',name:'Model A'},{id:'model-b',name:'Model B'}],connection:'configured'},savedState}={}){
 const dom=new JSDOM(module.exports.pipsDocument(),{runScripts:'outside-only',pretendToBeVisual:true});const w=dom.window;windows.push(w);const sent=[],answered=new Set(),observers=[];let interval,selectedOnce=false,persisted=savedState;
 if(observe)w.IntersectionObserver=class{constructor(callback){this.callback=callback;this.targets=[];this.disconnected=false;observers.push(this);}observe(node){this.targets.push(node);}disconnect(){this.disconnected=true;}};
 w.HTMLCanvasElement.prototype.getContext=()=>null;
 w.TextEncoder=TextEncoder;w.setInterval=fn=>{interval=fn;return 1;};w.acquireVsCodeApi=()=>({postMessage:m=>sent.push(m),getState:()=>persisted,setState:value=>{persisted=value;}});if(manualMount)delete w.acquireVsCodeApi;w.eval(code);
 const controller=manualMount?w.DgcPips.mount({root:w.document,postMessage:m=>sent.push(m),onMessage:listener=>{const handle=event=>listener(event.data);w.addEventListener("message",handle);return()=>w.removeEventListener("message",handle);}}):null;
 const message=data=>w.dispatchEvent(new w.MessageEvent('message',{data}));
 const answer=(request,result,ok=true)=>{answered.add(request.id);message({type:'pipsReply',id:request.id,ok,...(ok?{result}:{error:result})});};
 const requests=type=>sent.filter(m=>m.type==='pipsRequest'&&m.request.type===type);
 const defaults=request=>{
  switch(request.type){case 'list_pip_models':return modelsValue;case 'list_pip_messages':return{pip_id:request.pip_id,workspace_id:workspaceValue.id,messages:messages.filter(m=>m.pip_id===request.pip_id),next_before_id:null,active_run:chatActive,history_context_omitted_count:0};case 'list_pip_types':return{types:typesValue};case 'list_workspaces':return{workspaces:[workspaceValue],current_workspace_id:workspaceValue.id};case 'list_pips':return{pips:jobs};case 'get_pip_runner':return{runner:runnerValue};case 'get_workspace_context':return{context:contextValue};case 'get_pip':return{pip:jobs.find(j=>j.id===request.pip_id)};case 'list_pip_runs':return{runs:runs.filter(r=>r.pip_id===request.pip_id)};case 'get_pip_run':return{run:runs.find(r=>r.id===request.run_id)};default:return undefined;}
 };
 async function drain(overrides={}){for(let round=0;round<12;round++){await flush();const todo=sent.filter(m=>m.type==='pipsRequest'&&!answered.has(m.id));let count=0;for(const m of todo){const result=m.request.type in overrides?overrides[m.request.type](m.request):defaults(m.request);if(result!==undefined){answer(m,result);count++;}}await flush();if(autoSelect&&!selectedOnce&&!w.document.querySelector('#create-form')&&!w.document.querySelector('.type-picker')){const first=w.document.querySelector('[data-job]');if(first){selectedOnce=true;if(!w.document.querySelector('[data-job][aria-current=true]')){first.click();count++;}}}if(!conversation&&w.document.querySelector('.hero')&&w.document.querySelector('[data-tab=chat][aria-pressed=true]')){w.document.querySelector('[data-tab=runs]').click();count++;}if(!count)break;}await flush();}
 message({type:'pipsConnection',apiVersion,connected:true,supported:true,enabled});
 return{controller,w,d:w.document,observers,getPersisted:()=>persisted,sent,answered,message,answer,requests,drain,poll:()=>interval(),click:s=>{const el=w.document.querySelector(s);assert.ok(el,'Missing '+s);el.click();},input:(s,value)=>{const e=w.document.querySelector(s);e.value=value;e.dispatchEvent(new w.Event('input',{bubbles:true}));},submit:s=>w.document.querySelector(s).dispatchEvent(new w.Event('submit',{bubbles:true,cancelable:true}))};
}
test('disabled local Pips requires explicit enable, never requests a web account',async()=>{const x=setup({enabled:false});await x.drain();assert.equal(x.requests('list_workspaces').length,0);x.click('#enable');assert.equal(x.requests('pips_enable')[0].request.enabled,true);x.answer(x.requests('pips_enable')[0],{enabled:true,message:'Enabled'});await x.drain();assert.match(x.d.body.textContent,/Auditor a/);assert.doesNotMatch(x.d.body.textContent,/sign in|pair account/i);});
test('current workspace report is escaped and labels assessment, excerpt, and no tests',async()=>{const x=setup({jobs:[job('a',{name:'<img src=x onerror=alert(1)>'})]});await x.drain();assert.equal(x.d.querySelectorAll('img').length,0);assert.match(x.d.body.textContent,/<img src=x/);assert.match(x.d.body.textContent,/No tests were run/);assert.match(x.d.body.textContent,/Context\d+ records?/);assert.match(x.d.body.textContent,/aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa/);assert.equal(x.d.querySelectorAll('.dgc-plush').length,2);});
test('manual run requires live independent supervisor while emergency stop survives missing status',async()=>{const x=setup({runnerValue:{...runner,status:'offline',online:false}});await x.drain();assert.equal(x.d.querySelector('#run').disabled,true);assert.ok(x.d.querySelector('#start-runner'));assert.equal(x.d.querySelector('#stop-all').disabled,false);x.click('#refresh');await x.drain({get_pip_runner:()=>undefined});const pending=x.requests('get_pip_runner').find(m=>!x.answered.has(m.id));x.answer(pending,{message:'Status unavailable'},false);await x.drain();assert.equal(x.d.querySelector('#stop-all').disabled,false);});
test('late Pip response cannot replace a newly selected Pip',async()=>{const x=setup({jobs:[job('a'),job('b')],runs:[run('r1','a'),run('r2','b')]});await x.drain({get_pip:req=>req.pip_id==='a'?undefined:{pip:job('b')}});const old=x.requests('get_pip')[0];x.click('[data-job=b]');await x.drain({get_pip:req=>req.pip_id==='a'?undefined:{pip:job('b')}});assert.match(x.d.querySelector('.hero').textContent,/Auditor b/);x.answer(old,{pip:job('a')});await flush();assert.match(x.d.querySelector('.hero').textContent,/Auditor b/);assert.doesNotMatch(x.d.querySelector('[aria-label="Run report"]').textContent,/r1/);});
test('late report reply cannot replace the user’s newer run selection',async()=>{const x=setup({runs:[run('r1'),run('r2')]});await x.drain({get_pip_run:req=>req.run_id==='r1'?undefined:{run:run('r2')}});const old=x.requests('get_pip_run')[0];x.click('[data-run=r2]');await x.drain({get_pip_run:req=>req.run_id==='r1'?undefined:{run:run('r2')}});x.answer(old,{run:run('r1')});await flush();assert.match(x.d.querySelector('[aria-label="Run report"]').textContent,/r2/);assert.doesNotMatch(x.d.querySelector('[aria-label="Run report"]').textContent,/r1/);});
// The founder approved one of two waiting changes, saw the other vanish and the page say "Change
// recorded." for good: it read as both approved. The other was set aside (written for the same
// version); the review says so first, the notice says what happened, and then it goes.
test('accepting one of two changes for the same version says the other is set aside, and the notice fades',async()=>{
 const change=(id,goal)=>({id,expected_version:1,status:'proposed',definition:{name:'Auditor a',goal,source_ref:'HEAD'},reason:'Review source'});
 const x=setup({jobs:[job('a',{proposals:[change('proposal-1','New goal'),change('proposal-2','Other goal')]})]});await x.drain();
 x.click('[data-tab=revisions]');x.click('[data-proposal=proposal-1]');
 assert.match(x.d.querySelector('[role=dialog]').textContent,/Another change for this Pip is waiting too\. .*sets that one aside\. It is not approved\./);
 const timers=[];x.w.setTimeout=(fn,ms)=>{timers.push({fn,ms});return timers.length;};x.w.clearTimeout=()=>{};
 x.click('#review-confirm');x.answer(x.requests('accept_pip_update')[0],{});await flush();await x.drain();
 const notice=()=>x.d.querySelector('.notice[role=status]')?.textContent||'';
 assert.equal(notice(),'Auditor a is updated. The other waiting change was set aside, not approved.');
 const fade=timers.find(t=>t.ms>=4000);assert.ok(fade&&fade.ms<=15000,'the notice is timed to fade');
 fade.fn();assert.equal(notice(),'','gone after its reading time');
 assert.doesNotMatch(x.d.body.textContent,/Change recorded/);
});
