function bridge(){
 const documents=[],shown=[],saved=[];const posted=[],sent=[],created=[],revealed=[];let receive,disposed;const backend={};const panel={visible:true,webview:{cspSource:'vscode-webview:',asWebviewUri:x=>({toString:()=>x}),postMessage:m=>posted.push(m),onDidReceiveMessage:fn=>{receive=fn;}},onDidDispose:fn=>{disposed=fn;},onDidChangeViewState:()=>{},reveal:column=>revealed.push(column),dispose:()=>disposed?.()};
 const vs={workspace:{openTextDocument:async value=>{documents.push(value);return {...value,uri:'untitled:pip-result'};}},commands:{executeCommand:async (...args)=>saved.push(args)},window:{showTextDocument:async (...args)=>shown.push(args),createWebviewPanel:(...args)=>{created.push(args);return panel;}},ViewColumn:{Active:1},Uri:{joinPath:(_root,...parts)=>parts.join('/')}};
 const out={exports:{}};new Function('module','exports','require',view)(out,out.exports,name=>name==='vscode'?vs:require(name));
 const caps={pips_supported:true,pips_api_version:9,pips_enabled:false};let editor;editor=new out.exports.PipsEditor({},m=>{sent.push(m);return true;},()=>editor.ready(caps,backend));editor.open();
 return{editor,posted,sent,receive:m=>receive(m),backend,caps,panel,created,revealed,documents,shown,saved};
}
test('host correlates direct results and never forwards unowned replies',()=>{const x=bridge();x.receive({type:'pipsRequest',id:'one',request:{type:'get_pip_runner'}});const wire=x.sent[0];assert.equal(wire.type,'pips_control');assert.notEqual(wire.request.request_id,'one');const count=x.posted.length;x.editor.event({type:'pips_result',request_id:'unowned',command:'get_pip_runner',ok:true,result:{runner}});assert.equal(x.posted.length,count);x.editor.event({type:'pips_result',request_id:wire.request.request_id,command:'get_pip_runner',ok:true,result:{runner}});assert.equal(x.posted.at(-1).id,'one');assert.equal(x.posted.at(-1).ok,true);});
