const pipClaim=(extra={})=>({schema_version:1,id:'memory_'+'0'.repeat(32),pip_id:memoryPip,workspace_id:memoryWorkspace,kind:'fact',title:'Boundary assumption',statement:'Empty inputs are expected from callers.',reason:'Recorded in the Pips view.',anchor:pipClaimAnchor(),anchor_digest:'9'.repeat(64),created_at:'2026-10-02T01:00:00.000Z',created_by:'user',expires_at:null,classification:'user_recorded_claim',verification:'not_execution_verified',effect:'reference_only',digest:'a'.repeat(64),status:'active',revision:0,revoked_at:null,revoked_by:null,revoke_reason:null,...extra});
const pipClaimPage=(entries=[{memory:pipClaim(),effective_status:'active'}],extra={})=>({pip_id:memoryPip,workspace_id:memoryWorkspace,as_of:'2026-10-02T02:00:00.000Z',entries,counts:{retained:entries.length,active:entries.filter(e=>e.effective_status==='active').length,expired:entries.filter(e=>e.effective_status==='expired').length,revoked:entries.filter(e=>e.effective_status==='revoked').length},returned_records:entries.length,remaining_records:0,next_before_id:null,has_more:false,page_reduced_for_budget:false,...extra});
