test('Pip statements validate exact anchors, bounded authorship, reference semantics and lifecycle',()=>{
 const m=pipClaim();assert.equal(model.exports.pipStatement(m,memoryPip,memoryWorkspace),m);assert.equal(model.exports.pipStatementCandidate(pipClaimCandidate(),memoryPip,memoryWorkspace).anchor.source_reference,null);
 const source={run_id:memoryRun,checkpoint_id:1,checkpoint_digest:'b'.repeat(64),checkpoint_digest_kind:'stored_checkpoint_utf8',job_version:1,source_policy:{mode:'committed_only'},source_revision:'a'.repeat(40),source_snapshot:null,context_reference:{revision:1,digest:'c'.repeat(64)}};
 assert.equal(model.exports.pipStatementAnchor(pipClaimAnchor({source_reference:source,source_semantics:'selected_audit_reference'})).source_reference,source);
 for(const change of [{source_semantics:'verified'},{source_reference:source},{lifecycle_revision:true},{job_version:1000000},{context_reference:{revision:2147483648,digest:'f'.repeat(64)}},{binding:{...m.anchor.binding,root:'/private'}},{pip_id:memoryPip+'\n'},{source_reference:{...source,checkpoint_digest_kind:'canonical_json'},source_semantics:'selected_audit_reference'}])assert.throws(()=>model.exports.pipStatementCandidate(pipClaimCandidate(change),memoryPip,memoryWorkspace));
 for(const change of [{classification:'verified_fact'},{effect:'instruction'},{verification:'tests_passed'},{anchor:pipClaimAnchor({pip_id:'pip_'+'f'.repeat(32)})},{title:'Bad\ntitle'},{statement:'🎯'.repeat(501)},{statement:'\ud800'},{reason:''},{expires_at:m.created_at},{status:'revoked'},{revision:1},{digest:m.digest+'\n'},{anchor_digest:m.anchor_digest+'\n'},{extra:true}])assert.throws(()=>model.exports.pipStatement(pipClaim(change),memoryPip,memoryWorkspace));
 assert.equal(model.exports.pipStatement(pipClaim({kind:'preference',classification:'user_recorded_preference'})).kind,'preference');
});
