// Policy version 2 (2026-10-14): helpers share their Patch run's lifetime with no request, tool, output or time limit.
// The fixtures above are version 1, as a run saved before then carries it, and still read.
const specialistRunV2=()=>{const r=specialistRun();r.manifest.specialists={...specialistPolicyValue(),version:2,limits:{calls:1,requests:0,tool_calls:0,output_tokens_per_request:0,wall_seconds:0}};r.manifest.limits={iterations:0,tool_calls:0,wall_seconds:0};
 const calls=[{...specialistResult().calls[0],requests:20,model_calls:20,transport_attempts:20,tool_calls:90}];r.result={...r.result,tools_called:100,specialists:{...specialistResult(),version:2,calls,requests:30,model_calls:30,transport_attempts:30,output_token_reservations:30*16384,tool_calls:100}};return r;};
test('version-2 helpers have no request, tool or output limit, and a record never mixes the two versions',()=>{
 const r=specialistRunV2(),action=r.manifest.handoff.payload.action,check=(result,manifest=r.manifest)=>model.exports.specialistReceipt(result,manifest,action);
 assert.equal(check(r.result).requests,30,'past the old twelve requests, 64 tool calls and 4,096 tokens a request');
 assert.throws(()=>check({...r.result,specialists:{...r.result.specialists,version:1}}),'a receipt claims its own policy version');
 assert.throws(()=>check(r.result,{...r.manifest,limits:{iterations:12,tool_calls:64,wall_seconds:300}}),'version 2 runs say no limits');
 assert.throws(()=>check(r.result,{...r.manifest,specialists:{...r.manifest.specialists,limits:{...specialistPolicyValue().limits}}}),'version 2 with version 1 numbers');
 assert.throws(()=>check(r.result,{...r.manifest,specialists:{...r.manifest.specialists,version:3}}));
 const v1=specialistRun();assert.equal(check(v1.result,v1.manifest).version,1,'a saved version-1 run still reads');
 assert.throws(()=>check({...v1.result,specialists:{...specialistResult(),requests:13}},v1.manifest),'and keeps its bounds');
});
