const quillAutomationManifest=(trigger='schedule')=>{
 const occurrence={job_version:2,anchor_at:'2026-10-01T09:00:00.000Z',expected_next_due:'2026-10-01T10:00:00.000Z',scheduled_at:'2026-10-01T10:00:00.000Z',next_due_at:'2026-10-01T11:00:00.000Z',checked_at:'2026-10-01T10:03:00.000Z'};
 const m={pip_id:'pip_'+'1'.repeat(32),workspace_id:'ws_'+'2'.repeat(32),pip_type:'quill',job_version:2,job:{pip_type:'quill',name:'QA writer',goal:'Draft a source guide.',source_ref:'HEAD',model_choice:{mode:'default'},source_policy:{mode:'committed_only'}},requested_by:trigger==='schedule'?'local-scheduler':'local-event-trigger',tools:['glob','grep','read_file','repo_map','todo'],run_kind:'draft',policy:'read_only',source_policy:{mode:'committed_only'},source_revision:'a'.repeat(40),source_snapshot:null,trigger};
 if(trigger==='schedule'){m.schedule=interval(60);m.scheduled_at=occurrence.scheduled_at;}
 else m.event_trigger={policy:{events:['session_turn_completed'],minimum_minutes:15,missed_policy:'coalesce_latest'},job_version:2,expected_after_seq:3,checked_at:'2026-10-01T10:03:00.000Z',event:{seq:8,event_id:'event-eight',event_type:'workspace_session_turn_completed',created_at:'2026-10-01T10:00:00.000Z'},history_may_be_incomplete:false,source_semantics:'Current approved committed source at enqueue; event metadata does not select a historical checkout.'};
 m.draft_automation={schema_version:1,pip_id:m.pip_id,workspace_id:m.workspace_id,job_version:2,definition_digest:'b'.repeat(64),job_digest:'c'.repeat(64),trigger,policy:trigger==='schedule'?m.schedule:m.event_trigger.policy,occurrence:trigger==='schedule'?occurrence:Object.fromEntries(Object.entries(m.event_trigger).filter(([key])=>!['policy','source_semantics'].includes(key))),digest:'d'.repeat(64)};
 return m;
};
