function emailReview(status='pending'){return {id:emailActionId,pip_id:'a',workspace_id:'ws',source_run_id:emailRunId,status,digest:'d'.repeat(64),expires_at:'2099-10-05T06:00:00Z',payload:{schema_version:1,kind:'gmail_send',source:{run_id:emailRunId,pip_id:'a',workspace_id:'ws',job_version:1,lifecycle_revision:0,result_digest:'e'.repeat(64)},server:'composio',connection_digest:'a'.repeat(64),schema_digest:'b'.repeat(64),account:'ca_home',message:emailMessage},receipt:status==='succeeded'?{provider:'Gmail',message_id:'message1',meaning:'Provider accepted the message; delivery to the recipient is not confirmed.'}:null};}
