async function emailForm(x){x.click('#prepare-message');await x.drain({list_pip_connections:()=>({connections:[{name:'composio',provider:'Composio',enabled:true,pip_read_adapter:true}]})});x.click('[data-message-connection=composio]');await x.drain({list_pip_accounts:()=>({server:'composio',connection_digest:'a'.repeat(64),accounts:[{id:'ca_home',label:'Home',toolkit:'gmail'}]}),inspect_pip_send_connection:()=>({server:'composio',connection_digest:'a'.repeat(64),tool:'GMAIL_SEND_EMAIL',schema_digest:'b'.repeat(64),account_required:true})});}
function fillEmail(x){choose(x,'#message-account','0');x.input('#message-recipient',emailMessage.recipient_email);x.input('#message-subject',emailMessage.subject);x.input('#message-body',emailMessage.body);}
